#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long mod;
    cin >> n >> mod;

    vector<long long> mem_list = {0, 1};
    long long total = 1;

    auto add_mod = [&](long long a, long long b) {
        return (a + b) % mod;
    };

    auto multiply_mod = [&](long long a, long long b) {
        return (a * b) % mod;
    };

    for (int i = 2; i <= n; ++i) {
        int limit = (int)std::sqrt(i) + 1;
        long long current_sum = total;

        for (int f = 2; f < limit; ++f) {
            current_sum = add_mod(current_sum, mem_list[i / f]);
        }

        int boundary = i;
        for (int j = 1; j <= i / limit; ++j) {
            int nxt = i / (j + 1);
            current_sum = add_mod(current_sum, multiply_mod(boundary - nxt, mem_list[j]));
            boundary = nxt;
        }

        total = add_mod(total, current_sum);
        mem_list.push_back(current_sum);
    }

    cout << mem_list.back() << "\n";

    return 0;
}
